package cryptosquare

import (
	"math"
	"strings"
	"unicode"
)

// Encode normalizes the plaintext (lower-casing and removing spaces and
// punctuation), lays it out in a rectangle as square as possible, and reads
// it back column by column, emitting c chunks of r characters separated by
// spaces. Chunks that fall short of the full rectangle are padded with a
// single trailing space.
func Encode(pt string) string {
	var msg strings.Builder
	for _, r := range pt {
		if unicode.IsLetter(r) || unicode.IsDigit(r) {
			msg.WriteRune(unicode.ToLower(r))
		}
	}
	n := msg.Len()
	if n == 0 {
		return ""
	}

	c := int(math.Ceil(math.Sqrt(float64(n))))
	r := (n + c - 1) / c

	var out strings.Builder
	for col := 0; col < c; col++ {
		if col > 0 {
			out.WriteByte(' ')
		}
		for row := 0; row < r; row++ {
			if idx := row*c + col; idx < n {
				out.WriteByte(msg.String()[idx])
			} else {
				out.WriteByte(' ')
			}
		}
	}
	return out.String()
}

